import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"23、【剥】 坤下艮上","description":"温公易说 - 23、【剥】 坤下艮上","frontmatter":{"title":"23、【剥】 坤下艮上","description":"温公易说 - 23、【剥】 坤下艮上"},"headers":[],"relativePath":"zh/classics/wengong/024.md","filePath":"zh/classics/wengong/024.md"}'),n={name:"zh/classics/wengong/024.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_23、【剥】-坤下艮上" tabindex="-1">23、【剥】 坤下艮上 <a class="header-anchor" href="#_23、【剥】-坤下艮上" aria-label="Permalink to “23、【剥】 坤下艮上”">​</a></h1><h3 id="彖曰-剥-剥也-柔变刚也。不利有攸往-小人长也。顺而止之-观象也。君子尚消息盈虚-天行也。" tabindex="-1">彖曰：剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。 <a class="header-anchor" href="#彖曰-剥-剥也-柔变刚也。不利有攸往-小人长也。顺而止之-观象也。君子尚消息盈虚-天行也。" aria-label="Permalink to “彖曰：剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。”">​</a></h3><h3 id="象曰-山附于地-剥。上以厚下安宅。" tabindex="-1">象曰：山附于地，剥。上以厚下安宅。 <a class="header-anchor" href="#象曰-山附于地-剥。上以厚下安宅。" aria-label="Permalink to “象曰：山附于地，剥。上以厚下安宅。”">​</a></h3><p>剥以厚下安宅，夫基薄则墙隤，下薄则上危。故君子厚其下者，所以自安其居也。</p><h3 id="初六-剥床以足-蔑贞凶-象曰-剥床以足-以灭下也。" tabindex="-1">初六：剥床以足，蔑贞凶 象曰：剥床以足，以灭下也。 <a class="header-anchor" href="#初六-剥床以足-蔑贞凶-象曰-剥床以足-以灭下也。" aria-label="Permalink to “初六：剥床以足，蔑贞凶 象曰：剥床以足，以灭下也。”">​</a></h3><h3 id="六二-剥床以辨-蔑贞凶-象曰-剥床以辨-未有与也。" tabindex="-1">六二：剥床以辨，蔑贞凶 象曰：剥床以辨，未有与也。 <a class="header-anchor" href="#六二-剥床以辨-蔑贞凶-象曰-剥床以辨-未有与也。" aria-label="Permalink to “六二：剥床以辨，蔑贞凶 象曰：剥床以辨，未有与也。”">​</a></h3><h3 id="六三-剥之-无咎-象曰-剥之无咎-失上下也。" tabindex="-1">六三：剥之，无咎 象曰：剥之无咎，失上下也。 <a class="header-anchor" href="#六三-剥之-无咎-象曰-剥之无咎-失上下也。" aria-label="Permalink to “六三：剥之，无咎 象曰：剥之无咎，失上下也。”">​</a></h3><h3 id="六四-剥床以肤-凶-象曰-剥床以肤-切近灾也。" tabindex="-1">六四：剥床以肤，凶 象曰：剥床以肤，切近灾也。 <a class="header-anchor" href="#六四-剥床以肤-凶-象曰-剥床以肤-切近灾也。" aria-label="Permalink to “六四：剥床以肤，凶 象曰：剥床以肤，切近灾也。”">​</a></h3><h3 id="六五-贯鱼-以宫人宠-无不利-象曰-以宫人宠-终无尤也。" tabindex="-1">六五：贯鱼，以宫人宠，无不利 象曰：以宫人宠，终无尤也。 <a class="header-anchor" href="#六五-贯鱼-以宫人宠-无不利-象曰-以宫人宠-终无尤也。" aria-label="Permalink to “六五：贯鱼，以宫人宠，无不利 象曰：以宫人宠，终无尤也。”">​</a></h3><h3 id="上九-硕果不食-君子得舆-小人剥庐-象曰-君子得舆-民所载也。小人剥庐-终不可用也。" tabindex="-1">上九：硕果不食，君子得舆，小人剥庐 象曰：君子得舆，民所载也。小人剥庐，终不可用也。 <a class="header-anchor" href="#上九-硕果不食-君子得舆-小人剥庐-象曰-君子得舆-民所载也。小人剥庐-终不可用也。" aria-label="Permalink to “上九：硕果不食，君子得舆，小人剥庐 象曰：君子得舆，民所载也。小人剥庐，终不可用也。”">​</a></h3><p>硕果不食，将坠于地而复生也。剥之为道，举卦皆阴而上独以阳乘之，犹衰世之君子独立不惧，以制群阴。虽不当位，民所载也。或者阴来伐之，则是小人得志，君子道穷，祸乱遂成，民无所庇矣。诗云：人之云亡，邦国殄瘁，此之谓也。</p>',11)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
